// Added 2026-08-16. This endpoint was previously OPEN — anyone could POST to it and burn
// OpenAI tokens on the hardcoded test lead. It is only a fallback now that VIO-operator-agent-v2
// carries the real agent, but an open endpoint on a shared box is not worth keeping for that.
const expected = $env.VIO_WEBHOOK_TOKEN;
const item = $input.item.json;
const q = item.query || {};
const headers = item.headers || {};
const got = q.t || q.token || headers['x-vio-token'];
if (!expected) throw new Error('REFUSED: VIO_WEBHOOK_TOKEN not set (fail-closed)');
if (!got || String(got) !== String(expected)) throw new Error('REFUSED: bad or missing token');
return { json: item.body || item };

// validate_config — mirrors reach-engine/engine.py's validate_config() exactly.
// The config is the contract: nothing downstream runs against a config that fails this.
// Config embedded here matches config-oryoniq.json — keep both in sync if the campaign changes.
const cfg = {
  product: 'OryonIQ',
  one_liner: 'AI market intelligence for GovCon — surfaces federal pursuits before the RFP.',
  icp: {
    person_titles: ['Capture Manager', 'VP of Business Development', 'Director of Business Development', 'Proposal Manager'],
    person_locations: ['United States'],
    q_keywords: 'government contracting',
  },
  signal: 'The Pentagon suspended CMMC Phase II on July 13, 2026, and DoD committed $32B to AI, cloud, and cyber in H1 FY2026 — federal set-asides are opening fast.',
  offer: "OryonIQ flags the pursuits that fit your NAICS and SDB status before the RFP drops, so you're bidding while everyone else is still searching.",
  cta: 'https://www.oryoniq.com/contact',
  sender: 'Ellen\nOryonIQ, VisioneerIT',
  personalization_prompt: 'Write ONE specific opening line (max 2 sentences) for a cold email to {first_name}, {title} at {company} — a US government contractor. Tie the current signal to their capture/BD reality. Do NOT invent specific facts about {company}; keep it about their role and the signal.',
};

const REQUIRED_STR = ['product', 'one_liner', 'signal', 'offer', 'cta', 'sender', 'personalization_prompt'];
const errors = [];
for (const key of REQUIRED_STR) {
  const v = cfg[key];
  if (typeof v !== 'string' || !v.trim()) errors.push(`'${key}' must be a non-empty string`);
  else if (v.includes('<') && v.includes('>')) errors.push(`'${key}' still has a template placeholder`);
}
if (!cfg.icp || typeof cfg.icp !== 'object') errors.push("'icp' must be an object");
else {
  if (!Array.isArray(cfg.icp.person_titles) || !cfg.icp.person_titles.length) errors.push("'icp.person_titles' must be a non-empty list");
  if (!Array.isArray(cfg.icp.person_locations) || !cfg.icp.person_locations.length) errors.push("'icp.person_locations' must be a non-empty list");
}
for (const token of ['{first_name}', '{company}']) {
  if (!cfg.personalization_prompt.includes(token)) errors.push(`'personalization_prompt' must contain ${token}`);
}

const lead = $input.first().json;
return [{ json: { valid: errors.length === 0, errors, config_summary: `${cfg.product}: ${cfg.one_liner}`, signal: cfg.signal, offer: cfg.offer, cta: cfg.cta, sender: cfg.sender, first_name: lead.first_name, title: lead.title, company: lead.company } }];

// Assembles the final email exactly like reach-engine/engine.py's assemble_email(), then
// reports what ran — this is the deterministic precursor to the full autonomous agent
// (see VIOwf4agent0001's history: the true @n8n/n8n-nodes-langchain.agent node hit an
// unresolved 'model.includes is not a function' error connecting to the Chat Model sub-node;
// this sequence proves the two underlying tools work correctly while that gets debugged
// separately, ideally with UI access for clearer error context).
const cfg = $('validate_config').first().json;
const opener = $input.first().json.choices[0].message.content.trim().replace(/^"|"$/g, '');
const email = `Hi ${cfg.first_name},\n\n${opener}\n\n${cfg.offer}\n\nWant the three it's surfacing for a firm like yours? ${cfg.cta}\n\n${cfg.sender}`;
return [{ json: { ran: ['validate_config', 'personalize'], config_valid: true, lead: `${cfg.first_name} · ${cfg.title} · ${cfg.company}`, opener, email } }];
